// Pass org_id/client_id through from the webhook and roll every queried row
// into the agents[] list the callback expects.
const trigger = $node["Webhook"].json.body || {};
const rows = $input.all();
const agents = rows.map((r) => ({
  agent_name: r.json.agent_name,
  customer_contact: r.json.customer_contact,
  campaign_id: r.json.campaign_id,
  is_customer_replied: r.json.is_customer_replied,
  customer_last_reply: r.json.customer_last_reply,
  customer_last_reply_at: r.json.customer_last_reply_at,
  is_agent_replied: r.json.is_agent_replied,
  agent_last_reply: r.json.agent_last_reply,
  agent_last_reply_at: r.json.agent_last_reply_at,
  is_open: r.json.is_open,
  created_at: r.json.created_at
}));
return [{ json: { org_id: trigger.org_id, client_id: trigger.client_id, agents } }];
